package day3;

public class Weekly_Assignment_Even_Odd {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=0;
		for(;num<=20;) 
		{
			if(num%2==0) 
			{
				System.out.println (num +" is even number");
			}
			else {
				System.out.println( num +" is odd number") ;
			}
			num++;
			
		}

	}

}
